{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, the closest structural analog sharing the dimethoxybenzo-fused core, has a very low mean oral systemic availability of 0.049 ± 0.032 in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C64"],
      "claim": "Individual tetrabenazine oral bioavailability values are consistently below 10% (e.g., 7.4%, 5.3%, 8.5%, 1.3%, 0.5%, 0.1%, 2.0%), far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a prodrug ester of dihydrotetrabenazine, has about 49% absolute oral bioavailability, but the query lacks the ester prodrug motif and is more closely related to the parent tetrabenazine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Donepezil has near-complete oral bioavailability, but its structural overlap with the query is limited to a dimethoxyaryl and basic amine motif, which is insufficient to outweigh the tetrabenazine-like low-bioavailability evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the query is structurally closest to tetrabenazine, whose absolute oral bioavailability is consistently below 10%; the higher-bioavailability analogs are less transferable due to different scaffolds or prodrug mechanisms.",
  "evidence_gaps": [
    "No direct human or animal bioavailability measurement exists for the exact query molecule.",
    "The query's lactam and basic side chain may alter first-pass metabolism relative to tetrabenazine, but this is not supported by direct evidence.",
    "The relevance of valbenazine's higher bioavailability is uncertain because the query is not an ester prodrug of dihydrotetrabenazine."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
    {
